"""Fixed vendor log parser for maintenance log analysis."""

import csv
import sys


def summarize(path: str) -> dict[str, int]:
    counts = {"ok": 0, "malformed": 0, "high": 0}
    with open(path, newline="", encoding="utf-8") as handle:
        for row in csv.DictReader(handle):
            temperature = row["temperature_c"]
            # Bug 1 fix: Check if temperature exists before converting
            if temperature is None or temperature.strip() == "":
                counts["malformed"] += 1
                continue
            temperature = float(temperature)
            # Bug 2 fix: Use >= 350.0 for inclusive upper limit
            if temperature >= 350.0:
                counts["high"] += 1
            else:
                counts["ok"] += 1
    return counts


if __name__ == "__main__":
    print(summarize(sys.argv[1]))
